using Crm.__Module__.Validation;

namespace Crm.__Module__.Models;

/// <summary>Example aggregate generated by make module-new: replace it with the module's own model.</summary>
internal sealed class Item
{
    public Item(Guid id, string name, DateTimeOffset createdAt)
    {
        Id = id;
        Name = ItemRules.RequireValidName(name);
        CreatedAt = createdAt;
    }

    /// <summary>For EF Core.</summary>
    private Item()
    {
        Name = string.Empty;
    }

    public Guid Id { get; private set; }

    public string Name { get; private set; }

    public DateTimeOffset CreatedAt { get; private set; }
}
